    private void linkMenu(){
        if(selected==null || selectedBlock==null){message("Tap a writing area or table cell first.");return;}
        final EditText field=selected;final int start=Math.min(field.getSelectionStart(),field.getSelectionEnd()),end=Math.max(field.getSelectionStart(),field.getSelectionEnd());
        if(start<0)return;
        if(start!=end){prompt("Web address for “"+field.getText().subSequence(start,end)+"”","https://",url->{field.setSelection(start,end);applyFormat("link",SafeLinks.requireWeb(url));});return;}
        for(Note.Mark mark:TextStyles.read(field.getText()))if(mark.type.equals("link") && mark.start<=start && mark.end>start){
            choose("Link · "+field.getText().subSequence(mark.start,mark.end),new String[]{"Open link","Edit link","Remove link"},choice->{selected=field;field.setSelection(mark.start,mark.end);if(choice==0)openLink();else if(choice==1)prompt("Web address (http/https)",mark.value,url->{field.setSelection(mark.start,mark.end);applyFormat("link",SafeLinks.requireWeb(url));});else{List<Note.Mark> marks=new ArrayList<>(TextStyles.read(field.getText()));marks.removeIf(value->value.type.equals("link") && value.start==mark.start && value.end==mark.end && value.value.equals(mark.value));formattingChange=true;try{TextStyles.reflow(field,marks);}finally{formattingChange=false;}}});return;
        }
        final String key=field.getTag().toString(),blockId=selectedBlock;final RichText original=new RichText(field.getText().toString(),TextStyles.read(field.getText()));
        prompt("Text to display","",label->{if(label.trim().isEmpty())throw new IllegalArgumentException("Enter text to display");prompt("Web address (http/https)","https://",url->{RichText rich=RichLinks.insert(original,start,label,url);DocumentContent all=host.current().content;DocumentContent.Block block=all.block(blockId),next;
            if(key.startsWith("text:"))next=DocumentContent.Block.text(blockId,rich);
            else if(key.startsWith("cell:")){String[] parts=key.split(":");next=DocumentContent.Block.table(blockId,block.name,block.table.withRichCell(Integer.parseInt(parts[parts.length-2]),Integer.parseInt(parts[parts.length-1]),rich));}
            else{List<Note.Item> rows=new ArrayList<>(block.items);String item=key.substring(4);for(int i=0;i<rows.size();i++)if(rows.get(i).id.equals(item)){Note.Item old=rows.get(i);rows.set(i,new Note.Item(old.id,rich.text,old.checked,old.depth,rich.marks));}next=DocumentContent.Block.checklist(blockId,block.name,rows,block.hideChecked);}
            content(all.replace(blockId,next),true,null);
            state.putString("note",host.current().id);state.putString("field",key);state.putInt("start",start+label.length());state.putInt("end",start+label.length());
            postOnAnimation(()->{EditText updated=fields.get(key);if(updated!=null){updated.requestFocus();updated.setSelection(Math.min(updated.length(),start+label.length()));saveState();}});
        });});
    }
